sys_script_fix.script:
function getDuplicateValues(table, field){
var dupValues = [];
var ga = new GlideAggregate(table);
ga.addAggregate('COUNT', field);
ga.addNotNullQuery(field);
ga.groupBy(field);
ga.addHaving('COUNT', '>', 1);
ga.setLimit(100);
ga.query();
while (ga.next()) {
dupValues.push(ga[field].toString());
}
return dupValues;
}
var dupes = getDuplicateValues('cmn_location', 'name');
var locArr = [];
for (var i = 0; i < dupes.length; i++) {
var duplicates = new GlideRecord('cmn_location');
duplicates.addEncodedQuery('sys_class_name=cmn_location^name=');
duplicates.addEncodedQuery('name='+dupes[i]);
//duplicates.addEncodedQuery('');
duplicates.query();
while (duplicates.next()){
gs.info(duplicates.sys_id+'');
locArr.push(duplicates.sys_id+'');
}
}
gs.info(locArr.length);
gs.info(locArr);


